import numpy as np
from scipy.special import logsumexp


def q228(logits, labels, smoothing=0.1):
    x = np.asarray(logits, float)
    logp = x - logsumexp(x, axis=1, keepdims=True)
    return float(
        np.mean(
            -(1 - smoothing) * logp[np.arange(len(x)), labels]
            - smoothing * logp.mean(1)
        )
    )
